import'dart:convert';import'package:http/http.dart'as http;import'package:shared_preferences/shared_preferences.dart';class ApiClient{final String baseUrl;ApiClient({this.baseUrl='http://10.0.2.2:3000'});Future<String?> token()async=>(await SharedPreferences.getInstance()).getString('token');Future<Map<String,dynamic>> post(String path,Map<String,dynamic> body)async{final t=await token();final r=await http.post(Uri.parse('$baseUrl$path'),headers:{'Content-Type':'application/json',if(t!=null)'Authorization':'Bearer $t'},body:jsonEncode(body));if(r.statusCode>=400)throw Exception(r.body);return jsonDecode(r.body) as Map<String,dynamic>;}Future<List<dynamic>> getList(String path)async{final t=await token();final r=await http.get(Uri.parse('$baseUrl$path'),headers:{if(t!=null)'Authorization':'Bearer $t'});if(r.statusCode>=400)throw Exception(r.body);return jsonDecode(r.body) as List<dynamic>;}}